(()=>{const C=window.DUCK_ADMIN_CONFIG||{};const root=document.querySelector('#root');let token=localStorage.getItem('duck_admin_token')||'',view='dashboard',data={};const money=n=>new Intl.NumberFormat('fa-IR').format(Number(n||0));const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const api=async(path,opt={})=>{const headers={'Content-Type':'application/json',...(opt.headers||{})};if(token)headers.Authorization=`Bearer ${token}`;const r=await fetch(C.apiBase.replace(/\/$/,'')+path,{...opt,headers});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'API error');return d};const toast=m=>{const x=document.createElement('div');x.className='toast';x.textContent=m;document.body.appendChild(x);setTimeout(()=>x.remove(),1800)};
function login(){root.innerHTML=`<section class="login"><div class="logo">DUCK <span>STORE</span></div><h1>Admin Control Center</h1><p>کلید ادمین Cloudflare را وارد کن. کلید هرگز داخل GitHub ذخیره نمی‌شود.</p><input id="key" type="password" placeholder="ADMIN_KEY"><button class="btn primary" id="go" style="width:100%;margin-top:10px">ورود امن</button></section>`;document.querySelector('#go').onclick=async()=>{try{const r=await api('/api/admin/login',{method:'POST',body:JSON.stringify({key:document.querySelector('#key').value})});token=r.token;localStorage.setItem('duck_admin_token',token);render()}catch(e){toast(e.message)}}}
async function load(){try{const [dash,services,market,orders,users,coupons,tickets,settings,analytics,audit]=await Promise.all([api('/api/admin/dashboard'),api('/api/admin/services'),api('/api/admin/market'),api('/api/admin/orders'),api('/api/admin/users'),api('/api/admin/coupons'),api('/api/admin/tickets'),api('/api/admin/settings'),api('/api/admin/analytics'),api('/api/admin/audit')]);data={...dash,services:services.items||[],market:market.items||[],orders:orders.items||[],users:users.items||[],coupons:coupons.items||[],tickets:tickets.items||[],settings:settings.settings||{},analytics,audit:audit.items||[]};renderView()}catch(e){localStorage.removeItem('duck_admin_token');token='';login()}}
function render(){root.innerHTML=`<div class="layout"><aside class="side"><div class="logo">DUCK <span>STORE</span></div><div class="sub">ADMIN CONTROL CENTER</div><nav class="nav">${[['dashboard','⌂','داشبورد'],['services','✦','خدمات'],['market','◆','مارکت'],['orders','▣','سفارش‌ها'],['users','◌','کاربران'],['coupons','%','تخفیف‌ها'],['tickets','?','تیکت‌ها'],['analytics','↗','آنالیتیکس'],['settings','⚙','تنظیمات'],['audit','◷','لاگ امنیتی']].map(x=>`<button class="${view===x[0]?'active':''}" data-view="${x[0]}">${x[1]} &nbsp; ${x[2]}</button>`).join('')}</nav><button class="btn" id="logout" style="width:100%;margin-top:20px">خروج</button></aside><main class="content"><div class="top"><div><div class="muted">Duck Store / Admin</div><h1>${title(view)}</h1></div><div class="actions"><button class="btn" id="refresh">↻ بروزرسانی</button></div></div><div id="view"></div></main></div>`;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});document.querySelector('#logout').onclick=async()=>{try{await api('/api/admin/logout',{method:'POST'})}catch{}localStorage.removeItem('duck_admin_token');token='';login()};document.querySelector('#refresh').onclick=load;renderView()}
const title=v=>({dashboard:'داشبورد',services:'خدمات',market:'مارکت',orders:'سفارش‌ها',users:'کاربران',coupons:'کدهای تخفیف',tickets:'پشتیبانی',analytics:'آنالیتیکس',settings:'تنظیمات',audit:'Security Log'})[v];
function renderView(){if(!document.querySelector('#view'))return;document.querySelector('#view').innerHTML=({dashboard,services,market,orders,users,coupons,tickets,analytics,settings,audit})[view]();bind();}
function dashboard(){const s=data.stats||{};return `<div class="grid stats">${[['orders','کل سفارش'],['users','کاربر'],['services','خدمت فعال'],['market','محصول فعال'],['revenue','درآمد تکمیل‌شده']].map(x=>`<div class="card stat"><div class="muted">${x[1]}</div><b>${x[0]==='revenue'?money(s[x[0]])+' تومان':money(s[x[0]])}</b></div>`).join('')}</div><div class="split"><section class="card"><div class="row"><h3>آخرین سفارش‌ها</h3><span class="muted">${data.ticketCount||0} تیکت باز</span></div>${orderTable((data.orders||[]).slice(0,10))}</section><section class="card"><h3>وضعیت</h3><div class="grid"><div class="row"><span class="muted">API</span><b>Worker</b></div><div class="row"><span class="muted">DB</span><b>D1</b></div><div class="row"><span class="muted">Hosting</span><b>Pages</b></div><div class="row"><span class="muted">Repo</span><b>GitHub</b></div></div></section></div>`}
function orderTable(rows){return `<div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>کاربر</th><th>مبلغ</th><th>وضعیت</th><th>زمان</th><th>تغییر</th></tr></thead><tbody>${rows.map(o=>`<tr><td><b>${esc(o.id)}</b><div class="muted">${esc(o.title)}</div></td><td>${esc(o.username?'@'+o.username:o.first_name||o.telegram_id)}</td><td>${money(o.total)} ${o.currency==='XTR'?'⭐':'تومان'}</td><td>${pill(o.status)}</td><td>${esc(o.created_at)}</td><td><select data-order-status="${esc(o.id)}"><option value="pending" ${o.status==='pending'?'selected':''}>در انتظار</option><option value="processing" ${o.status==='processing'?'selected':''}>در حال انجام</option><option value="completed" ${o.status==='completed'?'selected':''}>تکمیل</option><option value="cancelled" ${o.status==='cancelled'?'selected':''}>لغو</option></select></td></tr>`).join('')}</tbody></table></div>`}
const pill=s=>`<span class="pill ${s==='completed'?'ok':s==='cancelled'?'danger':''}">${({pending:'در انتظار',processing:'در حال انجام',completed:'تکمیل‌شده',cancelled:'لغوشده'})[s]||s}</span>`;
function services(){return `<div class="toolbar"><div class="muted">قابل مدیریت بدون تغییر کد</div><button class="btn primary" id="newService">+ افزودن خدمت</button></div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>عنوان</th><th>دسته</th><th>قیمت</th><th>موجودی</th><th>ویژه</th><th>فعال</th><th>عملیات</th></tr></thead><tbody>${data.services.map(s=>`<tr><td><b>${esc(s.title)}</b><div class="muted">${esc(s.id)}</div></td><td>${esc(s.category)}</td><td>${money(s.price)} ${esc(s.unit)}</td><td>${s.stock<0?'∞':money(s.stock)}</td><td>${s.featured?'✓':'—'}</td><td>${s.active?'✓':'—'}</td><td><button class="btn" data-edit-service="${esc(s.id)}">ویرایش</button></td></tr>`).join('')}</tbody></table></div></section>`}
function market(){return `<div class="toolbar"><div class="muted">Gift Market catalog</div><button class="btn primary" id="newMarket">+ افزودن گیفت</button></div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Gift</th><th>قیمت</th><th>تخفیف</th><th>Rare</th><th>موجودی</th><th>عملیات</th></tr></thead><tbody>${data.market.map(m=>`<tr><td><b>${esc(m.name)} #${esc(m.number)}</b></td><td>${money(m.price)} ⭐</td><td>${money(m.discount)}%</td><td>${esc(m.rarity)}</td><td>${money(m.stock)}</td><td><button class="btn" data-edit-market="${esc(m.id)}">ویرایش</button></td></tr>`).join('')}</tbody></table></div></section>`}
function orders(){return `<div class="toolbar"><select id="orderFilter"><option value="">همه وضعیت‌ها</option><option value="pending">در انتظار</option><option value="processing">در حال انجام</option><option value="completed">تکمیل</option><option value="cancelled">لغو</option></select></div><section class="card">${orderTable(data.orders)}</section>`}
function users(){return `<section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>کاربر</th><th>خرید</th><th>هزینه</th><th>VIP</th><th>موجودی</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${data.users.map(u=>`<tr><td><b>${esc(u.first_name||'User')}</b><div class="muted">${esc(u.username?'@'+u.username:u.telegram_id)}</div></td><td>${money(u.order_count)}</td><td>${money(u.spend)}</td><td>${esc(u.vip_name||'Bronze')}</td><td>${money(u.balance)}</td><td>${u.blocked?'<span class="pill danger">Blocked</span>':'<span class="pill ok">Active</span>'}</td><td><button class="btn" data-block-user="${esc(u.telegram_id)}" data-blocked="${u.blocked?0:1}">${u.blocked?'رفع مسدودی':'مسدود'}</button></td></tr>`).join('')}</tbody></table></div></section>`}
function coupons(){return `<div class="toolbar"><div class="muted">کد درصدی یا مبلغ ثابت، محدودیت و تاریخ انقضا</div><button class="btn primary" id="newCoupon">+ کد جدید</button></div><section class="card"><table class="table"><thead><tr><th>کد</th><th>نوع</th><th>ارزش</th><th>استفاده</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${data.coupons.map(c=>`<tr><td><b>${esc(c.code)}</b></td><td>${esc(c.type)}</td><td>${money(c.value)}</td><td>${money(c.used_count)}/${c.usage_limit?money(c.usage_limit):'∞'}</td><td>${c.active?'فعال':'خاموش'}</td><td><button class="btn" data-edit-coupon="${esc(c.id)}">ویرایش</button></td></tr>`).join('')}</tbody></table></section>`}
function tickets(){return `<section class="card"><table class="table"><thead><tr><th>تیکت</th><th>کاربر</th><th>موضوع</th><th>اولویت</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${data.tickets.map(t=>`<tr><td>${esc(t.id)}</td><td>${esc(t.username?'@'+t.username:t.first_name||t.telegram_id)}</td><td>${esc(t.subject)}</td><td>${esc(t.priority)}</td><td>${pill(t.status)}</td><td><button class="btn" data-ticket="${esc(t.id)}">پاسخ</button></td></tr>`).join('')}</tbody></table></section>`}
function analytics(){return `<div class="grid stats"><div class="card"><div class="muted">۳۰ روز اخیر</div><b>${money((data.analytics.daily||[]).reduce((a,x)=>a+Number(x.orders||0),0))}</b><div class="muted">سفارش</div></div><div class="card"><div class="muted">درآمد ۳۰ روز</div><b>${money((data.analytics.daily||[]).reduce((a,x)=>a+Number(x.revenue||0),0))}</b><div class="muted">تومان</div></div></div><section class="card" style="margin-top:12px"><h3>پرفروش‌ترین خدمات</h3><table class="table"><thead><tr><th>خدمت</th><th>سفارش</th><th>درآمد</th></tr></thead><tbody>${(data.analytics.top||[]).map(x=>`<tr><td>${esc(x.title)}</td><td>${money(x.orders)}</td><td>${money(x.revenue)}</td></tr>`).join('')}</tbody></table></section>`}
function settings(){const s=data.settings||{};return `<section class="card"><div class="form"><div class="field"><label>عنوان فروشگاه</label><input id="set_store_title" value="${esc(s.store_title||'Duck Store')}"></div><div class="field"><label>Hero</label><input id="set_hero_text" value="${esc(s.hero_text||'همه‌چیز برای تلگرام، یک‌جا و تمیز.')}"></div><div class="field"><label>پشتیبانی</label><input id="set_support_url" value="${esc(s.support_url||'https://t.me/Zanjani_a')}"></div><div class="field"><label>کانال</label><input id="set_channel_url" value="${esc(s.channel_url||'https://t.me/duck_storee')}"></div><div class="field"><label>Reward Referral</label><input id="set_referral_reward" type="number" value="${esc(s.referral_reward||20000)}"></div><div class="field"><label>Cashback پیش‌فرض٪</label><input id="set_cashback_default" type="number" value="${esc(s.cashback_default||0)}"></div></div><button class="btn primary" id="saveSettings" style="margin-top:12px">ذخیره تنظیمات</button></section>`}
function audit(){return `<section class="card"><table class="table"><thead><tr><th>زمان</th><th>Actor</th><th>Action</th><th>Entity</th><th>Meta</th></tr></thead><tbody>${data.audit.map(a=>`<tr><td>${esc(a.created_at)}</td><td>${esc(a.actor_type)} / ${esc(a.actor_id)}</td><td>${esc(a.action)}</td><td>${esc(a.entity_type)} / ${esc(a.entity_id)}</td><td>${esc(a.meta_json)}</td></tr>`).join('')}</tbody></table></section>`}
function modal(title,html,save){const bg=document.createElement('div');bg.className='modal-bg';bg.innerHTML=`<section class="modal"><div class="row"><h3>${title}</h3><button class="btn" id="close">×</button></div>${html}<div class="actions" style="margin-top:14px"><button class="btn primary" id="save">ذخیره</button><button class="btn" id="cancel">انصراف</button></div></section>`;document.body.appendChild(bg);bg.querySelectorAll('#close,#cancel').forEach(x=>x.onclick=()=>bg.remove());bg.querySelector('#save').onclick=async()=>{try{await save(bg);bg.remove();toast('ذخیره شد');await load()}catch(e){toast(e.message)}}}
function serviceModal(s={}){modal(s.id?'ویرایش خدمت':'افزودن خدمت',`<div class="form"><div class="field"><label>نام</label><input id="title" value="${esc(s.title)}"></div><div class="field"><label>آیکون</label><input id="icon" value="${esc(s.icon||'✦')}"></div><div class="field"><label>دسته</label><input id="category" value="${esc(s.category||'general')}"></div><div class="field"><label>قیمت</label><input id="price" type="number" value="${Number(s.price||0)}"></div><div class="field"><label>قیمت قبل</label><input id="compare_at_price" type="number" value="${Number(s.compare_at_price||0)}"></div><div class="field"><label>حداقل</label><input id="min_qty" type="number" value="${Number(s.min_qty||1)}"></div><div class="field"><label>حداکثر</label><input id="max_qty" type="number" value="${Number(s.max_qty||1)}"></div><div class="field"><label>موجودی (-1 = نامحدود)</label><input id="stock" type="number" value="${Number(s.stock??-1)}"></div><div class="field"><label>ETA دقیقه</label><input id="eta_minutes" type="number" value="${Number(s.eta_minutes||0)}"></div><div class="field"><label>تگ‌ها</label><input id="tags" value="${esc(s.tags)}"></div><div class="field"><label>Featured</label><select id="featured"><option value="0">خیر</option><option value="1" ${s.featured?'selected':''}>بله</option></select></div><div class="field"><label>فعال</label><select id="active"><option value="1">بله</option><option value="0" ${!s.active?'selected':''}>خیر</option></select></div><div class="field"><label>ترتیب</label><input id="sort_order" type="number" value="${Number(s.sort_order||0)}"></div><div class="field full"><label>توضیح</label><textarea id="description" rows="3">${esc(s.description)}</textarea></div><div class="field full"><label>Rules</label><textarea id="rules" rows="2">${esc(s.rules)}</textarea></div><div class="field full"><label>Fields Schema JSON</label><textarea id="fields_schema" rows="4">${esc(s.fields_schema||'[]')}</textarea></div></div>`,w=>api('/api/admin/services',{method:s.id?'PUT':'POST',body:JSON.stringify({id:s.id,title:w.querySelector('#title').value,icon:w.querySelector('#icon').value,category:w.querySelector('#category').value,price:Number(w.querySelector('#price').value),compare_at_price:Number(w.querySelector('#compare_at_price').value),min_qty:Number(w.querySelector('#min_qty').value),max_qty:Number(w.querySelector('#max_qty').value),stock:Number(w.querySelector('#stock').value),eta_minutes:Number(w.querySelector('#eta_minutes').value),tags:w.querySelector('#tags').value,featured:w.querySelector('#featured').value==='1',active:w.querySelector('#active').value==='1',sort_order:Number(w.querySelector('#sort_order').value),description:w.querySelector('#description').value,rules:w.querySelector('#rules').value,fields_schema:w.querySelector('#fields_schema').value})}))}
function marketModal(m={}){modal(m.id?'ویرایش گیفت':'افزودن گیفت',`<div class="form"><div class="field"><label>نام</label><input id="name" value="${esc(m.name)}"></div><div class="field"><label>شماره</label><input id="number" type="number" value="${Number(m.number||0)}"></div><div class="field"><label>قیمت ⭐</label><input id="price" type="number" value="${Number(m.price||0)}"></div><div class="field"><label>قیمت قبل</label><input id="original_price" type="number" value="${Number(m.original_price||0)}"></div><div class="field"><label>تخفیف ٪</label><input id="discount" type="number" value="${Number(m.discount||0)}"></div><div class="field"><label>Rare</label><input id="rarity" value="${esc(m.rarity)}"></div><div class="field"><label>موجودی</label><input id="stock" type="number" value="${Number(m.stock||0)}"></div><div class="field"><label>Featured</label><select id="featured"><option value="0">خیر</option><option value="1" ${m.featured?'selected':''}>بله</option></select></div><div class="field"><label>فعال</label><select id="active"><option value="1">بله</option><option value="0" ${!m.active?'selected':''}>خیر</option></select></div><div class="field full"><label>Telegram URL</label><input id="telegram_url" value="${esc(m.telegram_url)}"></div><div class="field full"><label>Market URL</label><input id="market_url" value="${esc(m.market_url)}"></div></div>`,w=>api('/api/admin/market',{method:m.id?'PUT':'POST',body:JSON.stringify({id:m.id,name:w.querySelector('#name').value,number:Number(w.querySelector('#number').value),price:Number(w.querySelector('#price').value),original_price:Number(w.querySelector('#original_price').value),discount:Number(w.querySelector('#discount').value),rarity:w.querySelector('#rarity').value,stock:Number(w.querySelector('#stock').value),featured:w.querySelector('#featured').value==='1',active:w.querySelector('#active').value==='1',telegram_url:w.querySelector('#telegram_url').value,market_url:w.querySelector('#market_url').value})}))}
function couponModal(c={}){modal(c.id?'ویرایش کد':'کد تخفیف جدید',`<div class="form"><div class="field"><label>Code</label><input id="code" value="${esc(c.code)}"></div><div class="field"><label>Type</label><select id="type"><option value="percent" ${c.type==='percent'?'selected':''}>درصدی</option><option value="fixed" ${c.type==='fixed'?'selected':''}>مبلغ ثابت</option></select></div><div class="field"><label>Value</label><input id="value" type="number" value="${Number(c.value||0)}"></div><div class="field"><label>حداقل سفارش</label><input id="min_order" type="number" value="${Number(c.min_order||0)}"></div><div class="field"><label>حداکثر تخفیف</label><input id="max_discount" type="number" value="${Number(c.max_discount||0)}"></div><div class="field"><label>سقف استفاده</label><input id="usage_limit" type="number" value="${Number(c.usage_limit||0)}"></div><div class="field"><label>شروع</label><input id="starts_at" type="datetime-local" value="${esc((c.starts_at||'').slice(0,16))}"></div><div class="field"><label>پایان</label><input id="ends_at" type="datetime-local" value="${esc((c.ends_at||'').slice(0,16))}"></div></div>`,w=>api('/api/admin/coupons',{method:c.id?'PUT':'POST',body:JSON.stringify({id:c.id,code:w.querySelector('#code').value,type:w.querySelector('#type').value,value:Number(w.querySelector('#value').value),min_order:Number(w.querySelector('#min_order').value),max_discount:Number(w.querySelector('#max_discount').value),usage_limit:Number(w.querySelector('#usage_limit').value),starts_at:w.querySelector('#starts_at').value||null,ends_at:w.querySelector('#ends_at').value||null,active:true})}))}
function bind(){document.querySelectorAll('[data-order-status]').forEach(x=>x.onchange=async()=>{try{await api('/api/admin/orders/status',{method:'PATCH',body:JSON.stringify({id:x.dataset.orderStatus,status:x.value})});toast('وضعیت سفارش ذخیره شد');await load()}catch(e){toast(e.message)}});document.querySelector('#newService')?.addEventListener('click',()=>serviceModal());document.querySelectorAll('[data-edit-service]').forEach(b=>b.onclick=()=>serviceModal(data.services.find(s=>s.id===b.dataset.editService)));document.querySelector('#newMarket')?.addEventListener('click',()=>marketModal());document.querySelectorAll('[data-edit-market]').forEach(b=>b.onclick=()=>marketModal(data.market.find(s=>s.id===b.dataset.editMarket)));document.querySelector('#newCoupon')?.addEventListener('click',()=>couponModal());document.querySelectorAll('[data-edit-coupon]').forEach(b=>b.onclick=()=>couponModal(data.coupons.find(s=>s.id===b.dataset.editCoupon)));document.querySelectorAll('[data-block-user]').forEach(b=>b.onclick=async()=>{try{await api('/api/admin/users/block',{method:'PATCH',body:JSON.stringify({telegram_id:b.dataset.blockUser,blocked:b.dataset.blocked==='1'})});toast('وضعیت کاربر تغییر کرد');await load()}catch(e){toast(e.message)}});document.querySelectorAll('[data-ticket]').forEach(b=>b.onclick=()=>{const t=data.tickets.find(x=>x.id===b.dataset.ticket);modal('پاسخ به تیکت',`<div class="field"><label>${esc(t.subject)}</label><textarea id="reply" rows="8"></textarea></div>`,w=>api('/api/admin/tickets/reply',{method:'POST',body:JSON.stringify({ticket_id:t.id,message:w.querySelector('#reply').value})}))});document.querySelector('#saveSettings')?.addEventListener('click',async()=>{const b={store_title:document.querySelector('#set_store_title').value,hero_text:document.querySelector('#set_hero_text').value,support_url:document.querySelector('#set_support_url').value,channel_url:document.querySelector('#set_channel_url').value,referral_reward:document.querySelector('#set_referral_reward').value,cashback_default:document.querySelector('#set_cashback_default').value};try{await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(b)});toast('تنظیمات ذخیره شد');await load()}catch(e){toast(e.message)}});document.querySelector('#orderFilter')?.addEventListener('change',async e=>{const q=e.target.value?`?status=${encodeURIComponent(e.target.value)}`:'';try{const r=await api('/api/admin/orders'+q);data.orders=r.items||[];renderView()}catch(err){toast(err.message)}})}
if(!C.apiBase||C.apiBase.includes('REPLACE-')){root.innerHTML='<section class="login"><h1>API URL را تنظیم کن</h1><p>در admin/config.js آدرس Worker را جایگزین کن.</p></section>'}else if(token){load()}else{login()}
})();
